def is_multiple(n, a):
    r = n - 2 * a
    if r == 0:
        return True
    if r < 0:
        return False
    import math
    if r - 1 < 0 or r - 1 > a - 1:
        return True
    val = math.comb(a - 1, r - 1)
    return val % r == 0

results = []
for n in range(2, 200):
    if n % 2 == 0 or n % 3 == 0:
        continue
    possible_a = [a for a in range(1, n) if n // a == 2]
    all_a_pass = True
    for a in possible_a:
        if not is_multiple(n, a):
            all_a_pass = False
            break
    if all_a_pass:
        results.append(n)
print(f"Count: {len(results)}")
print(f"List: {results}")
